const e="ca-2026-07-sec2-sebis-july-reform-bundle",t="ca_note",a="current-affairs",o="Sebi's July Reform Bundle",s='**A.** Unpaid client securities → payout to demat + auto-pledge into "CUSPA" account.',n=[{id:"blk-16-bullets",type:"bullet_list",items:['**A.** Unpaid client securities → payout to demat + auto-pledge into "CUSPA" account.',"**B.** FPI fee shift to rupee: $1,000 → **₹90,000**; Category-I FPI/FVCI registration $2,500 → ₹2.3 lakh; custodian fee ₹10L annual → ₹85,000/month.","**C.** MF intraday borrowing allowed (additional to existing 20% of net assets cap for redemptions).","**D.** IPF income: depositories can use up to 5% for admin expenses (≥95% must be ploughed back).","**E.** Staff conduct: 2-yr cooling-off for ex-employees; gift disclosure threshold ₹10,000→₹50,000; equity investment barred for employees.","**F.** SWP/STP standing instructions now allowed for demat-held MF units (phased: unit-based by 31 Jan 2027, amount-based by 30 Apr 2027).","**G.** ₹1 crore penalty on CDSL for 2022 cybersecurity lapse (46-54.5 hr disruption).","**H.** MF death-claim rules eased: AMCs can use latest address; self-certified ID for name mismatch.","**I.** PMS reform proposal: MF-only PMS category; min investment ₹50L→₹25L; net worth ₹5cr→₹2cr; fee capped at 2.5% AUM.","**J.** Security transmission fast-track (QTP): ≤₹10,000 (physical)/₹30,000 (demat); processing within 21 days."]},{id:"blk-16-trap",type:"exam_trap",content:"🎯 Exam Angle → 🔥 HIGH — FPI fee figures ($1,000→₹90,000) are the standout trap."}],i={exam:["SBI PO Mains 2026","IBPS PO Mains 2026","RBI Grade B 2026"],tags:["current-affairs","2026-07","sec2","claude-core-v3"],category:"SEC2",sectionCode:"SEC2",difficulty:"advanced",relevanceTier:"TIER_A",noteTier:"TIER_A",date:"2026-07-17",period:"2026-07",monthLabel:"JULY 2026",monthGroup:"2026-07",provenance:{sourceSystem:"Claude",sourceFile:"current_affairs_July2026_core.md",sourceTitle:"Sebi's July Reform Bundle"},noteNumber:117},r=[],c={id:e,type:t,domain:a,title:o,summary:s,blocks:n,metadata:i,relationships:r};export{n as blocks,c as default,a as domain,e as id,i as metadata,r as relationships,s as summary,o as title,t as type};
